package com.thangit.boardinghouse.service;

import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.repository.*;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Paged management projections; amounts always come from the existing financial sources. */
@Service
public class ManagementReportService {
 private final JdbcClient db;private final AdminReportRepository reports;
 public ManagementReportService(JdbcClient db,AdminReportRepository reports){this.db=db;this.reports=reports;}
 public record Filter(String type,Long propertyId,Long organizationId,Long areaId,LocalDate startDate,LocalDate endDate,String keyword,String status,String category,Long roomId,Long contractId,String sort,int page,int size){}
 private static final Set<String> TYPES=Set.of("overview","operations","occupancy","revenue","payments","expenses","profit","debt","invoices","deposits","contracts","tenants","residences","bookings","utilities","services","maintenance","assets");
 private static final Set<String> FINANCIAL=Set.of("revenue","payments","expenses","profit","debt","invoices","deposits","utilities","services");
 private record Context(String type,List<Long> ids,List<Long> financial,Map<String,Object> args){}
 private Context context(AuthenticatedUser a,Filter f){
  String type=Objects.toString(f.type(),"overview").toLowerCase(Locale.ROOT);
  if(a==null||!Set.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT,RoleCode.TECHNICIAN).contains(a.activeRole())||a.activeRole()==RoleCode.TECHNICIAN&&!Set.of("maintenance","assets").contains(type))throw denied();
  if(a.activeRole()==RoleCode.ACCOUNTANT&&!db.sql("SELECT EXISTS(SELECT 1 FROM accountant_profiles WHERE user_id=:id)").param("id",a.id()).query(Boolean.class).single())throw denied();
  if(!TYPES.contains(type)||f.startDate()==null||f.endDate()==null||f.endDate().isBefore(f.startDate())||f.endDate().isAfter(f.startDate().plusYears(2))||f.page()<0||f.size()<1||f.size()>100)throw bad("REPORT_FILTER_INVALID");
  var allowed=reports.properties(a.id(),a.activeRole()).stream().map(p->p.id()).toList();
  if(f.propertyId()!=null&&!allowed.contains(f.propertyId()))throw denied();
  List<Long> ids=f.propertyId()==null?allowed:List.of(f.propertyId());
  var groupArgs=new HashMap<String,Object>();groupArgs.put("ids",safe(ids));String group="";
  if(f.organizationId()!=null){group+=" AND organization_id=:org";groupArgs.put("org",f.organizationId());}if(f.areaId()!=null){group+=" AND area_id=:area";groupArgs.put("area",f.areaId());}
  if(!group.isEmpty())ids=db.sql("SELECT property_id FROM organization_property_relationships WHERE ended_at IS NULL AND property_id IN (:ids)"+group).params(groupArgs).query(Long.class).list();
  var financial=a.activeRole()==RoleCode.TECHNICIAN?List.<Long>of():a.activeRole()==RoleCode.MANAGER?db.sql("SELECT property_id FROM manager_property_capabilities WHERE manager_id=:actor AND capability='FINANCE_READ' AND property_id IN (:ids)").param("actor",a.id()).param("ids",safe(ids)).query(Long.class).list():ids;
  if(FINANCIAL.contains(type)){if(f.propertyId()!=null&&!financial.contains(f.propertyId()))throw denied();ids=financial;}
  var args=new HashMap<String,Object>();args.put("ids",safe(ids));args.put("financeIds",safe(financial));args.put("start",f.startDate());args.put("until",f.endDate().plusDays(1));args.put("today",com.thangit.boardinghouse.service.BusinessTime.today(InvoicePaymentRules.ZONE));args.put("actor",a.id());
  return new Context(type,ids,financial,args);
 }
 @Transactional(readOnly=true) public Map<String,Object> choices(AuthenticatedUser a,long property){if(a==null||a.activeRole()==RoleCode.TECHNICIAN)throw denied();LocalDate today=com.thangit.boardinghouse.service.BusinessTime.today(InvoicePaymentRules.ZONE);context(a,new Filter("overview",property,null,null,today,today,null,null,null,null,null,null,0,20));return Map.of("rooms",db.sql("SELECT id,code FROM rooms WHERE property_id=:property ORDER BY code,id").param("property",property).query().listOfRows(),"contracts",db.sql("SELECT c.id,c.code,c.room_id roomId FROM contracts c JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:property ORDER BY c.code,c.id").param("property",property).query().listOfRows());}
 @Transactional(readOnly=true) public List<Map<String,Object>> options(AuthenticatedUser a){LocalDate today=com.thangit.boardinghouse.service.BusinessTime.today(InvoicePaymentRules.ZONE);context(a,new Filter(a!=null&&a.activeRole()==RoleCode.TECHNICIAN?"assets":"overview",null,null,null,today,today,null,null,null,null,null,null,0,20));return propertyOptions(a);}
 private List<Map<String,Object>> propertyOptions(AuthenticatedUser a){var all=reports.properties(a.id(),a.activeRole()).stream().map(p->p.id()).toList();return db.sql("SELECT p.id,p.name,opr.organization_id organizationId,opr.area_id areaId,o.name organizationName,ma.name areaName FROM properties p LEFT JOIN organization_property_relationships opr ON opr.property_id=p.id AND opr.ended_at IS NULL LEFT JOIN organizations o ON o.id=opr.organization_id LEFT JOIN management_areas ma ON ma.id=opr.area_id WHERE p.id IN (:ids) ORDER BY p.name").param("ids",safe(all)).query().listOfRows();}
 @Transactional(readOnly=true) public Map<String,Object> read(AuthenticatedUser a,Filter f){
  var c=context(a,f);var out=new LinkedHashMap<String,Object>();
  out.put("type",c.type());out.put("propertyIds",c.ids());out.put("financialPropertyIds",c.financial());out.put("startDate",f.startDate());out.put("endDate",f.endDate());out.put("updatedAt",com.thangit.boardinghouse.service.BusinessTime.now(InvoicePaymentRules.ZONE));
  out.put("properties",propertyOptions(a));
  var summary=a.activeRole()==RoleCode.TECHNICIAN?new LinkedHashMap<String,Object>():new LinkedHashMap<String,Object>(reports.roomSummary(a.id(),a.activeRole(),c.ids()));
  if(a.activeRole()!=RoleCode.TECHNICIAN)summary.put("occupancyRate",ReportKpis.occupancy(summary.get("occupiedRooms"),summary.get("availableRooms")));
  if(!c.financial().isEmpty())summary.putAll(new ManagementFinanceRepository(db).summary(c.financial(),f.startDate(),f.endDate()));
  if(a.activeRole()!=RoleCode.TECHNICIAN){summary.put("activePeople",scalar("SELECT COUNT(DISTINCT tr.tenant_profile_id) FROM tenant_residences tr WHERE tr.property_id IN (:ids) AND tr.status='ACTIVE' AND tr.room_id IS NOT NULL AND tr.move_in_date<=:today AND (tr.move_out_date IS NULL OR tr.move_out_date>:today)",c.args()));
  summary.put("expiringContracts",scalar("SELECT COUNT(*) FROM contracts c JOIN rooms r ON r.id=c.room_id WHERE r.property_id IN (:ids) AND c.status IN ('ACTIVE','EXPIRING') AND c.end_date BETWEEN :today AND DATE_ADD(:today,INTERVAL 30 DAY)",c.args()));
  }out.put("summary",summary);
  out.put("definitions",Map.of("occupancyRate","Hiện tại: phòng OCCUPIED/NOTICE chia phòng không INACTIVE/MAINTENANCE. Giữ chỗ chưa phải đang thuê. Quy ước 0% khi không có phòng đủ điều kiện.","roomDays","Chưa có lịch sử điều kiện khai thác đủ để tính mẫu số room-days; không dùng trạng thái hiện tại làm xu hướng quá khứ.","revenue","Nghĩa vụ hóa đơn theo kỳ sử dụng, không phải tiền thực thu hay doanh thu kế toán dồn tích. Chi tiết khoản thu là trước giảm giá; tổng ròng dùng total_amount của hóa đơn.","cash","Giao dịch nguồn hợp lệ theo ngày thực nhận/trả, không cộng lại biên lai. Cọc/khách trả trước/thu hộ được phân loại riêng.","debt","Số dư nghĩa vụ hợp lệ hiện tại của tất cả kỳ, không lọc bỏ nợ cũ theo ngày lập. Không phải ảnh chụp công nợ tại ngày cuối khoảng chọn.","deposits","Số dư cọc hiện tại, mức yêu cầu không phải tiền thực nhận.","financialScope","KPI tiền chỉ tính nhà trọ được cấp FINANCE_READ; nhà không được cấp quyền có giá trị tài chính trống.","history","Cư trú theo khoảng giao nhau với thời gian chọn; số người phân biệt với lượt cư trú. Không xuất CCCD.","services","Số lượng theo từng đơn vị. Chưa phân bổ thanh toán hoặc giảm giá vào từng dịch vụ, không suy diễn thực thu dịch vụ.","maintenance","actual_cost là chi phí ghi tại công việc; số duyệt lấy đề xuất APPROVED mới nhất, không cộng các bản đề xuất. Chưa có liên kết thực chi thì để trống, không suy diễn."));
  out.put("trend",db.sql("SELECT period,SUM(obligations) obligations,SUM(cash_in) cashIn,SUM(cash_out) cashOut FROM (SELECT DATE_FORMAT(billing_period,'%Y-%m') period,total_amount obligations,0 cash_in,0 cash_out FROM invoices WHERE property_id IN (:financeIds) AND billing_period>=:start AND billing_period<:until AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') UNION ALL SELECT DATE_FORMAT(occurred_at,'%Y-%m'),0,cash_in,cash_out FROM management_cash_events WHERE property_id IN (:financeIds) AND occurred_at>=:start AND occurred_at<:until) t GROUP BY period ORDER BY period").params(c.args()).query().listOfRows());
  out.put("roomStatuses",a.activeRole()==RoleCode.TECHNICIAN?List.of():reports.roomStatuses(a.id(),a.activeRole(),c.ids()));
  out.put("costCategories",db.sql("SELECT category,COALESCE(SUM(amount),0) amount FROM management_expense_events WHERE property_id IN (:financeIds) AND occurred_on>=:start AND occurred_on<:until GROUP BY category").params(c.args()).query().listOfRows());
  String source=source(a,c);out.put("statuses",db.sql("SELECT DISTINCT q.status FROM ("+source+") q WHERE q.property_id IN (:ids) AND q.status IS NOT NULL ORDER BY q.status").params(c.args()).query(String.class).list());var args=new HashMap<>(c.args());String where=" WHERE q.property_id IN (:ids)";
  if(text(f.keyword())!=null){where+=" AND (q.code LIKE :keyword OR q.property_name LIKE :keyword)";args.put("keyword","%"+f.keyword().trim()+"%");}
  if(text(f.status())!=null){if("contracts".equals(c.type())&&"EXPIRING_WINDOW".equals(f.status()))where+=" AND q.status IN ('ACTIVE','EXPIRING') AND q.days_remaining BETWEEN 0 AND 30";else{where+=" AND q.status=:status";args.put("status",f.status());}}
  if(text(f.category())!=null){where+=" AND q.category=:category";args.put("category",f.category());}
  if(f.roomId()!=null){if(Set.of("overview","operations","services","expenses","profit","deposits").contains(c.type()))throw bad("REPORT_ROOM_FILTER_UNSUPPORTED");where+=" AND q.room_id=:room";args.put("room",f.roomId());}
  if(f.contractId()!=null){if(!Set.of("revenue","invoices","debt","contracts","tenants","residences","utilities").contains(c.type()))throw bad("REPORT_CONTRACT_FILTER_UNSUPPORTED");where+=" AND q.contract_id=:contract";args.put("contract",f.contractId());}
  String base=" FROM ("+source+") q"+where;
  long count=db.sql("SELECT COUNT(*)"+base).params(args).query(Long.class).single();
  String extra=switch(c.type()){case "revenue","invoices","debt"->",SUM(q.paid_amount) paid_amount,SUM(q.remaining_amount) remaining_amount,COUNT(DISTINCT q.tenant_id) distinct_people";case "tenants","residences"->",COUNT(DISTINCT q.tenant_id) distinct_people";case "utilities"->",SUM(q.electricity_kwh) electricity_kwh,SUM(q.water_m3) water_m3";case "assets"->",SUM(q.quantity) asset_units";case "expenses"->",SUM(q.paid_amount) paid_amount,SUM(q.payable) payable";default->"";};
  var totals=db.sql("SELECT SUM(q.amount) amount,COUNT(*) rowCount"+extra+base).params(args).query().singleRow();
  String order=switch(Objects.toString(f.sort(),"")){case "amount"->"q.amount DESC,q.code";case "code"->"q.code,q.property_id";default->"q.event_date DESC,q.code,q.property_id";};
  args.put("limit",f.size());args.put("offset",Math.multiplyExact((long)f.page(),f.size()));
  var rows=db.sql("SELECT *"+base+" ORDER BY "+order+" LIMIT :limit OFFSET :offset").params(args).query().listOfRows();
  out.put("rows",rows);out.put("totalElements",count);out.put("totalPages",(count+f.size()-1)/f.size());out.put("page",f.page());out.put("filteredTotals",totals);
  out.put("detailBasis",switch(c.type()){case "debt","deposits","occupancy","assets","overview","operations"->"CURRENT_SNAPSHOT";case "revenue","invoices","services","utilities"->"BILLING_PERIOD";case "payments","expenses","profit"->"SOURCE_EVENT_DATE";default->"OVERLAP_OR_CREATED_IN_RANGE";});
  return out;
 }
 @Transactional public com.thangit.boardinghouse.dto.response.report.AdminReportResponses.ExportJob createExport(AuthenticatedUser a,Filter f,String format){
  var c=context(a,f);if(a.activeRole()==RoleCode.TECHNICIAN)throw denied();if(a.activeRole()==RoleCode.MANAGER&&db.sql("SELECT COUNT(*) FROM manager_property_capabilities WHERE manager_id=:actor AND capability='EXPORT' AND property_id IN (:ids)").param("actor",a.id()).param("ids",safe(c.ids())).query(Long.class).single()!=c.ids().size())throw denied();
  if(!Set.of("CSV","XLSX").contains(format))throw bad("REPORT_FORMAT_UNSUPPORTED");
  var table=new ArrayList<List<Object>>();table.add(List.of("Báo cáo quản trị",c.type(),f.startDate()+".."+f.endDate()));table.add(List.of("Người xuất",a.id(),"Phạm vi",c.ids().toString(),"Thời điểm",com.thangit.boardinghouse.service.BusinessTime.now(InvoicePaymentRules.ZONE).toString()));
  table.add(List.of("Cơ sở","Công nợ/cọc/phòng là snapshot hiện tại; nghĩa vụ theo kỳ; tiền theo ngày giao dịch. Không phải lợi nhuận pháp định."));
  List<String> columns=null;Map<?,?> totals=Map.of();
  for(int page=0;;page++){var data=read(a,new Filter(f.type(),f.propertyId(),f.organizationId(),f.areaId(),f.startDate(),f.endDate(),f.keyword(),f.status(),f.category(),f.roomId(),f.contractId(),f.sort(),page,100));totals=(Map<?,?>)data.get("filteredTotals");for(Object row:(List<?>)data.get("rows")){var r=(Map<?,?>)row;if(columns==null){columns=r.keySet().stream().map(Object::toString).toList();table.add(columns.stream().map(k->(Object)ReportColumns.title(k)).toList());}var cells=new ArrayList<Object>();for(String key:columns)cells.add(r.get(key));table.add(cells);}if(page+1>=((Number)data.get("totalPages")).longValue())break;}
  table.add(List.of("Số dòng",totals.getOrDefault("rowCount",null)==null?0:totals.get("rowCount"),"Tổng cột amount (theo cơ sở từng báo cáo)",Objects.toString(totals.get("amount"),"")));
  byte[] content;if(format.equals("XLSX"))content=InvoiceDocuments.workbook(table);else{var csv=new StringBuilder("\ufeff");for(var row:table)csv.append(String.join(",",row.stream().map(com.thangit.boardinghouse.common.validation.CsvCells::quote).toList())).append('\n');content=csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
  var meta=new LinkedHashMap<String,Object>();meta.put("role",a.activeRole().name());meta.put("propertyIds",c.ids());meta.put("financialPropertyIds",c.financial());meta.put("startDate",f.startDate().toString());meta.put("endDate",f.endDate().toString());meta.put("workspaceFilter",f.toString());
  long id=reports.saveExport(a.id(),c.type().toUpperCase(Locale.ROOT),format,meta,columns==null?List.of():columns,"bao-cao-"+c.type()+"-"+f.startDate()+"."+format.toLowerCase(Locale.ROOT),content);return reports.export(a.id(),id).orElseThrow();
 }
 private String source(AuthenticatedUser a,Context c){return switch(c.type()){
  case "revenue","invoices","debt" -> "SELECT i.id invoice_id,i.tenant_id,i.contract_id,i.room_id,i.property_id,p.name property_name,i.code, i.billing_period event_date,CASE WHEN i.remaining_amount>0 AND i.due_date<:today AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') THEN 'OVERDUE' ELSE i.status END status,'INVOICE' category,i.total_amount amount,COALESCE(tp.full_name,u.full_name) tenant_name,r.code room_code,c.code contract_code,i.issue_date,i.payment_available_from,i.due_date,i.paid_amount,i.remaining_amount,i.discount_amount,CASE WHEN i.remaining_amount>0 AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') THEN GREATEST(DATEDIFF(:today,i.due_date),0) ELSE 0 END overdue_days,ii.rent_amount,ii.electricity_amount,ii.water_amount,ii.service_amount FROM invoices i JOIN properties p ON p.id=i.property_id JOIN rooms r ON r.id=i.room_id JOIN contracts c ON c.id=i.contract_id LEFT JOIN tenant_profiles tp ON tp.id=c.tenant_profile_id LEFT JOIN users u ON u.id=i.tenant_id LEFT JOIN (SELECT invoice_id,SUM(IF(item_type='ROOM_RENT',amount,0)) rent_amount,SUM(IF(item_type='ELECTRICITY',amount,0)) electricity_amount,SUM(IF(item_type='WATER',amount,0)) water_amount,SUM(IF(item_type='SERVICE',amount,0)) service_amount FROM invoice_items GROUP BY invoice_id) ii ON ii.invoice_id=i.id WHERE i.property_id IN (:ids)"+("debt".equals(c.type())?" AND i.remaining_amount>0 AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')":" AND i.billing_period>=:start AND i.billing_period<:until"+("revenue".equals(c.type())?" AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')":""));
  case "payments","profit" -> "SELECT e.*,e.occurred_at event_date,e.classification category,'CONFIRMED' status,e.cash_in-e.cash_out amount,p.name property_name,py.invoice_id,i.room_id,COALESCE(py.reference_code,dt.reference_code,v.payment_reference,oi.reference_code) reference_code,COALESCE(u.full_name,'') confirmed_by,IF(e.method='BANK_TRANSFER','MANUAL_SOURCE_CONFIRMATION','SOURCE_CONFIRMATION') reconciliation_basis FROM management_cash_events e JOIN properties p ON p.id=e.property_id LEFT JOIN payments py ON e.source_type='PAYMENT' AND py.id=e.source_id LEFT JOIN invoices i ON i.id=py.invoice_id LEFT JOIN deposit_transactions dt ON e.source_type='DEPOSIT' AND dt.id=e.source_id LEFT JOIN payment_vouchers v ON e.source_type='VOUCHER' AND v.id=e.source_id LEFT JOIN other_income oi ON e.source_type='OTHER_INCOME' AND oi.id=e.source_id LEFT JOIN users u ON u.id=COALESCE(py.received_by,dt.transacted_by,v.paid_by,oi.created_by) WHERE e.property_id IN (:ids) AND e.occurred_at>=:start AND e.occurred_at<:until"+("payments".equals(c.type())?" AND e.cash_in>0":"");
  case "expenses" -> "SELECT e.*,CONCAT(e.source_type,'-',e.source_id) code,p.name property_name,e.occurred_on event_date,COALESCE(v.status,'CONFIRMED') status,IF(v.status='PAID',e.amount,0) paid_amount,IF(v.status='PAID',0,e.amount) payable,v.id voucher_id,v.payee_name FROM management_expense_events e JOIN properties p ON p.id=e.property_id LEFT JOIN payment_vouchers v ON (e.source_type='VOUCHER' AND v.id=e.source_id) OR (e.source_type='EXPENSE' AND v.expense_id=e.source_id AND v.status NOT IN ('REJECTED','REVERSED')) WHERE e.property_id IN (:ids) AND e.occurred_on>=:start AND e.occurred_on<:until";
  case "deposits" -> "SELECT d.id deposit_id,d.property_id,p.name property_name,COALESCE(c.code,b.code,CONCAT('COC-',d.id)) code,NULL event_date,d.reconciliation_status status,IF(d.contract_id IS NULL,'RESERVATION','SECURITY') category,d.balance_amount amount,d.required_amount,COALESCE(t.received_amount,0) received_amount,COALESCE(t.refunded_amount,0) refunded_amount,COALESCE(t.deducted_amount,0) deducted_amount,d.balance_amount,COALESCE(u.full_name,'') tenant_name FROM tenant_deposits d JOIN properties p ON p.id=d.property_id LEFT JOIN contracts c ON c.id=d.contract_id LEFT JOIN rental_bookings b ON b.id=d.booking_id LEFT JOIN users u ON u.id=d.tenant_id LEFT JOIN (SELECT deposit_id,SUM(IF(transaction_type IN ('COLLECT','TRANSFER_IN'),amount,0)) received_amount,SUM(IF(transaction_type='REFUND',amount,0)) refunded_amount,SUM(IF(transaction_type IN ('DEDUCT','FORFEIT'),amount,0)) deducted_amount FROM deposit_transactions WHERE status='CONFIRMED' GROUP BY deposit_id) t ON t.deposit_id=d.id WHERE d.property_id IN (:ids)";
  case "contracts" -> "SELECT c.id contract_id,r.id room_id,r.property_id,p.name property_name,c.code,c.start_date event_date,c.status,'CONTRACT' category,IF(r.property_id IN (:financeIds),c.agreed_monthly_rent,NULL) amount,IF(r.property_id IN (:financeIds),c.deposit_amount,NULL) deposit_amount,tp.full_name tenant_name,r.code room_code,c.start_date,c.end_date,DATEDIFF(c.end_date,:today) days_remaining FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN properties p ON p.id=r.property_id LEFT JOIN tenant_profiles tp ON tp.id=c.tenant_profile_id WHERE r.property_id IN (:ids) AND ((c.start_date<:until AND c.end_date>=:start) OR (c.status IN ('DRAFT','PENDING_CONFIRMATION') AND c.created_at>=:start AND c.created_at<:until))";
  case "tenants","residences" -> "SELECT tr.id residence_id,tr.tenant_profile_id tenant_id,tr.room_id,tr.contract_id,tr.property_id,p.name property_name,tp.tenant_code code,tr.move_in_date event_date,tr.status,tr.residence_role category,NULL amount,tp.full_name tenant_name,r.code room_code,r.capacity,tr.move_in_date,tr.move_out_date FROM tenant_residences tr JOIN tenant_profiles tp ON tp.id=tr.tenant_profile_id JOIN properties p ON p.id=tr.property_id LEFT JOIN rooms r ON r.id=tr.room_id WHERE tr.property_id IN (:ids) AND tr.room_id IS NOT NULL AND tr.move_in_date<:until AND (tr.move_out_date IS NULL OR tr.move_out_date>=:start)"+("tenants".equals(c.type())?" AND tr.status='ACTIVE' AND tr.room_id IS NOT NULL AND tr.move_in_date<=:today AND (tr.move_out_date IS NULL OR tr.move_out_date>:today)":"");
  case "bookings" -> "SELECT b.id booking_id,b.room_id,b.property_id,p.name property_name,b.code,b.created_at event_date,b.status,'RESERVATION' category,NULL amount,tp.full_name tenant_name,b.reservation_start,b.reservation_end FROM rental_bookings b JOIN properties p ON p.id=b.property_id LEFT JOIN tenant_profiles tp ON tp.id=b.tenant_profile_id WHERE b.property_id IN (:ids) AND b.created_at>=:start AND b.created_at<:until";
  case "utilities" -> "SELECT ur.id reading_id,r.id room_id,c.id contract_id,r.property_id,p.name property_name,r.code,ur.billing_period event_date,ur.reading_status status,'UTILITY' category,ur.electricity_amount+ur.water_amount amount,ur.electricity_previous,ur.electricity_current,COALESCE(ur.electricity_consumption,ur.electricity_current-ur.electricity_previous) electricity_kwh,ur.electricity_amount,ur.water_previous,ur.water_current,COALESCE(ur.water_consumption,ur.water_current-ur.water_previous) water_m3,ur.water_amount FROM utility_readings ur JOIN contracts c ON c.id=ur.contract_id JOIN rooms r ON r.id=c.room_id JOIN properties p ON p.id=r.property_id WHERE r.property_id IN (:ids) AND ur.billing_period>=:start AND ur.billing_period<:until";
  case "services" -> "SELECT MIN(i.property_id) property_id,p.name property_name,it.name code,MIN(i.billing_period) event_date,'ISSUED_SNAPSHOT' status,it.item_type category,SUM(it.amount) amount,it.unit,SUM(it.quantity) quantity,COUNT(DISTINCT i.contract_id) contract_count,NULL collected_amount FROM invoice_items it JOIN invoices i ON i.id=it.invoice_id JOIN properties p ON p.id=i.property_id WHERE i.property_id IN (:ids) AND i.billing_period>=:start AND i.billing_period<:until AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') AND it.item_type IN ('SERVICE','ELECTRICITY','WATER') GROUP BY i.property_id,p.name,it.name,it.unit,it.item_type";
  case "maintenance" -> "SELECT m.id maintenance_id,m.room_id,m.property_id,p.name property_name,m.code,m.created_at event_date,m.status,m.issue_type category,NULL amount,m.title,m.priority,m.sla_due_at,m.estimated_cost,m.actual_cost recorded_work_cost,mc.approved_cost,CASE WHEN EXISTS(SELECT 1 FROM maintenance_costs linked WHERE linked.maintenance_request_id=m.id AND linked.expense_id IS NOT NULL) THEN COALESCE((SELECT SUM(IF(v.status='PAID',v.amount,0)) FROM maintenance_costs linked JOIN payment_vouchers v ON v.expense_id=linked.expense_id WHERE linked.maintenance_request_id=m.id),0) END paid_cost,u.full_name assignee_name FROM maintenance_requests m JOIN properties p ON p.id=m.property_id LEFT JOIN users u ON u.id=m.assigned_to LEFT JOIN (SELECT cost.maintenance_request_id,cost.total_cost approved_cost FROM maintenance_costs cost JOIN (SELECT maintenance_request_id,MAX(id) approved_id FROM maintenance_costs WHERE approval_status='APPROVED' GROUP BY maintenance_request_id) latest ON latest.approved_id=cost.id) mc ON mc.maintenance_request_id=m.id WHERE m.property_id IN (:ids) AND m.created_at>=:start AND m.created_at<:until"+(a.activeRole()==RoleCode.TECHNICIAN?" AND m.assigned_to=:actor":"");
  case "assets" -> "SELECT a.id asset_id,r.id room_id,r.property_id,p.name property_name,a.name code,NULL event_date,a.condition_status status,'ASSET' category,NULL amount,a.quantity,r.code room_code,a.note,NULL depreciated_value FROM room_assets a JOIN rooms r ON r.id=a.room_id JOIN properties p ON p.id=r.property_id WHERE r.property_id IN (:ids)"+(a.activeRole()==RoleCode.TECHNICIAN?" AND EXISTS(SELECT 1 FROM maintenance_requests m WHERE m.asset_id=a.id AND m.assigned_to=:actor)":"");
  case "occupancy" -> "SELECT r.id room_id,r.property_id,p.name property_name,r.code,NULL event_date,r.status,'ROOM' category,NULL amount,EXISTS(SELECT 1 FROM tenant_residences tr WHERE tr.room_id=r.id AND tr.status='ACTIVE' AND tr.move_in_date<=:today AND (tr.move_out_date IS NULL OR tr.move_out_date>:today)) physical_residence FROM rooms r JOIN properties p ON p.id=r.property_id WHERE r.property_id IN (:ids)";
  default -> comparison();
 };}
 private String comparison(){return "SELECT p.id property_id,p.name property_name,p.name code,NULL event_date,p.status,'PROPERTY' category,IF(p.id IN (:financeIds),COALESCE(cash.incoming,0)-COALESCE(cash.outgoing,0),NULL) amount,COALESCE(r.total,0) total_rooms,COALESCE(r.occupied,0) occupied_rooms,ROUND(100*COALESCE(r.occupied,0)/NULLIF(r.available,0),2) occupancy_rate,IF(p.id IN (:financeIds),COALESCE(inv.obligations,0),NULL) invoice_obligations,IF(p.id IN (:financeIds),COALESCE(inv.debt,0),NULL) outstanding_debt,IF(p.id IN (:financeIds),COALESCE(cash.incoming,0),NULL) cash_in,IF(p.id IN (:financeIds),COALESCE(cash.outgoing,0),NULL) cash_out,IF(p.id IN (:financeIds),COALESCE(cost.amount,0),NULL) confirmed_costs FROM properties p LEFT JOIN (SELECT property_id,COUNT(*) total,SUM(status IN ('OCCUPIED','NOTICE')) occupied,SUM(status NOT IN ('INACTIVE','MAINTENANCE')) available FROM rooms WHERE property_id IN (:ids) GROUP BY property_id) r ON r.property_id=p.id LEFT JOIN (SELECT property_id,SUM(IF(billing_period>=:start AND billing_period<:until,total_amount,0)) obligations,SUM(remaining_amount) debt FROM invoices WHERE property_id IN (:financeIds) AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') GROUP BY property_id) inv ON inv.property_id=p.id LEFT JOIN (SELECT property_id,SUM(cash_in) incoming,SUM(cash_out) outgoing FROM management_cash_events WHERE property_id IN (:financeIds) AND occurred_at>=:start AND occurred_at<:until GROUP BY property_id) cash ON cash.property_id=p.id LEFT JOIN (SELECT property_id,SUM(amount) amount FROM management_expense_events WHERE property_id IN (:financeIds) AND occurred_on>=:start AND occurred_on<:until GROUP BY property_id) cost ON cost.property_id=p.id WHERE p.id IN (:ids)";}
 private BigDecimal scalar(String sql,Map<String,Object> args){return db.sql(sql).params(args).query(BigDecimal.class).single();}
 private static BigDecimal percent(Object n,Object d){var denominator=new BigDecimal(Objects.toString(d,"0"));return denominator.signum()==0?null:new BigDecimal(Objects.toString(n,"0")).multiply(BigDecimal.valueOf(100)).divide(denominator,2,RoundingMode.HALF_UP);}
 private static List<Long> safe(List<Long> ids){return ids.isEmpty()?List.of(-1L):ids;}private static String text(String v){return v==null||v.isBlank()?null:v.trim();}
 private static AuthException denied(){return new AuthException(HttpStatus.FORBIDDEN,"REPORT_SCOPE_DENIED","Không có quyền xem báo cáo hoặc phạm vi tài chính này.");}private static AuthException bad(String code){return new AuthException(HttpStatus.BAD_REQUEST,code,"Kiểm tra loại báo cáo, bộ lọc, khoảng ngày và phân trang.");}
}
